        }
        if (namesakeCount != null && namesakeCount == 0) {
            points += 1;
        }
        if (goldHousehold) {
            points += 2;
        }
        if (registrationDate != null
                && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > TENURE_DAYS) {
